export function safeName(value) {
	if (typeof value !== 'string')
		throw new TypeError('safeName expects a string');

	if (value.includes('..'))
		throw new Error(`unsafe name: ${value}`);

	return value;
}

import assert from 'node:assert/strict';
import test from 'node:test';

import { safeName } from './path.mjs';

// ACC-1 (mandatory): safeName must throw for values containing `..`.
test('throws for values containing ..', () => {
	for (const value of ['..', '../etc/passwd', 'a/../b', 'foo..bar', 'safe/..', '..hidden'])
		assert.throws(() => safeName(value), /unsafe name/, `expected throw for ${value}`);
});

test('returns values that do not contain ..', () => {
	for (const value of ['', 'file.txt', 'a/b/c', 'dot.separated.name', '.hidden'])
		assert.equal(safeName(value), value);
});

test('throws for non-string values', () => {
	for (const value of [null, undefined, 42, {}, ['..']])
		assert.throws(() => safeName(value), TypeError);
});

